def solve_sequence(N):
    a = [0] * (N + 1)
    if N >= 1:
        a[1] = 1
    if N >= 2:
        a[2] = 1

    for n in range(3, N + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}

        # Check if indices are within bounds (they should be if the sequence is well-defined for n up to N)
        try:
            term1 = a[a[n-1]]
        except IndexError:
            return f"Error: Index a_{n-1} is out of bounds for calculation of a_{n-1}"

        try:
            term2 = a[n - a[n-1]]
        except IndexError:
            return f"Error: Index n - a_{n-1} is out of bounds for calculation of a_{n-1}"

        a[n] = term1 + term2

    return a

# Calculate up to N=32 to verify the pattern for powers of 2
