def calculate_a(limit):
    a = {}
    a[1] = 1
    a[2] = 1
    for n in range(3, limit + 1):
        # a_n = a_{a_{n-1}} + a_{n - a_{n-1}}
        a_prev = a[n-1]

        # Check indices bounds for safety, though the definition ensures they are positive
        idx1 = a_prev
        idx2 = n - a_prev

        if idx1 not in a or idx2 not in a:
            # This should not happen if n >= 3 and a_n-1 >= 1
            print(f"Error calculating a_{n}: missing indices {idx1} or {idx2}")
            return {}

        a[n] = a[idx1] + a[idx2]
    return a

a_sequence = calculate_a(12)
print("a_1 to a_12:", [a_sequence[i] for i in range(1, 13)])
